 void monitorChart(std::wstring label,std::wstring key){auto panel=stack(false,6);panel.Children().Append(title(label,15));Canvas canvas;canvas.Height(70);canvas.Background(dark?brush(32,32,32):brush(248,248,248));Microsoft::UI::Xaml::Shapes::Polyline line;line.Stroke(accent());line.StrokeThickness(2);canvas.Children().Append(line);auto draw=[this,canvas,line,key](JsonObject){line.Points().Clear();auto now=clockSeconds();double width=std::max(1.0,canvas.ActualWidth());for(auto const& m:monitorHistory){auto v=m.GetNamedValue(key,JsonValue::CreateNullValue());if(v.ValueType()!=JsonValueType::Number){line.Points().Clear();continue;}double x=std::clamp(1.0-(now-num(m,L"sampleTime"))/60.0,0.0,1.0)*width;double y=66-std::clamp(v.GetNumber(),0.0,100.0)*0.62;line.Points().Append(Windows::Foundation::Point{(float)x,(float)y});}};onSizeChanged(canvas,[draw](auto const&,auto const&){draw(JsonObject{});});monitorBindings.push_back(draw);draw(monitoring());panel.Children().Append(canvas);panel.Children().Append(text(L"0–100% · 2 秒采样 · 不可用时留空",10,true));page.Children().Append(card(panel,12));}
